const rows = items.map(it => it.json);

// Case-insensitive field lookup, so this keeps working even if a
// column header's casing changes later (Status / status / STATUS, etc.)
const getField = (row, name) => {
  const key = Object.keys(row).find(
    k => k.trim().toLowerCase() === name.trim().toLowerCase()
  );
  return key !== undefined ? row[key] : undefined;
};

// Only rows where Status is empty (not yet processed)
const pending = rows.filter(r => {
  const status = String(getField(r, 'Status') ?? '').trim();
  return status === '';
});

if (!pending.length) {
  // Nothing left to process this run - stop here quietly, no error.
  return [];
}

// Process rows in Day order so nothing gets skipped
pending.sort((a, b) => {
  const da = Number(getField(a, 'Day'));
  const db = Number(getField(b, 'Day'));
  if (Number.isFinite(da) && Number.isFinite(db)) return da - db;
  return 0;
});

// Take exactly ONE row - this is what keeps the whole downstream
// pipeline (which is built for a single post at a time) from
// receiving multiple items in parallel and breaking the merges.
return [{ json: pending[0] }];

const j = $input.first().json || {};

const clean = (v, fallback = '') => {
  const s = String(v ?? '').trim();
  return s || fallback;
};

// --- Read the sheet row picked upstream ---
const day = j['Day'];
const contentAngle = clean(j['Content Angle'], 'Informational');
const hook = clean(j['Hook']);
const staticContent = clean(j['Static Post Content']);
const cta = clean(j['CTA'], 'Learn More');
const caption = clean(j['Caption']);

if (day === undefined || day === null || String(day).trim() === '') {
  throw new Error('The "Day" column is empty for this sheet row - it is needed to mark the row as posted later.');
}
if (!hook) {
  throw new Error('The "Hook" column is empty for this sheet row.');
}
if (!staticContent) {
  throw new Error('The "Static Post Content" column is empty for this sheet row.');
}

// Fixed brand colours (the colour-picker form has been removed, so these are locked defaults)
const primary = '#DC287F';
const secondary = '#0F254B';
const background = '#FFFFFF';
const text = '#000000';

const brandKit = `STUDY NURSING ABROAD — OFFICIAL BRAND GUIDELINES

BRAND POSITIONING
Tagline: Global Opportunities. A Healthier Tomorrow.
Brand words: Aspiring, Supportive, Global, Trustworthy, Empowering.
Brand mood: Clean & Modern, Human-Centric, Positive & Aspirational, Global & Trustworthy, Simple & Clear, Supportive & Friendly.

COLOUR SYSTEM FOR THIS RUN
Primary: ${primary} — CTA, highlighted headline words, icons, key accents.
Secondary: ${secondary} — headings, structural contrast, dividers, dark graphic areas.
Background: ${background} — principal canvas/background colour.
Text: ${text} — body/detail text.
Supporting tones may be used sparingly when compatible: Light Pink #FADBE9, Soft Pink #FFF5FA, Neutral #E6E6E6, Text Grey #444444.

TYPOGRAPHY
Use Poppins throughout. Strong bold headline, semibold subheadings, clean regular body copy. Maintain strong hierarchy, good line breaks, and mobile legibility.

CTA
Primary CTA is a fully rounded pill using the selected Primary colour with white bold text and a small chevron.

ICON STYLE
Simple line icons using the selected Primary colour inside soft/light circular badges when supported by the chosen reference.

VISUAL MOTIFS
Use only when supported by the chosen reference composition: dashed flight path, faint world map, subtle dot grid, soft abstract circles, travel/global context. Do not force every motif into every post.

PHOTOGRAPHY
Authentic, aspirational nurses or nursing students, natural expressions, professional appearance, realistic lighting. Use global/travel context only when relevant.

LOGO RULE
Never generate the Study Nursing Abroad logo or wordmark inside the AI-created image. Reserve a clean seamless top-left logo-safe area. The real logo is composited later. The reserved area must not look like a separate box, patch, panel, or placeholder.

PARTNER LOGO RULE (BOTTOM-RIGHT)
Also reserve a clean seamless area in the bottom-right corner of the canvas for a small partner logo and a one-line disclaimer that are composited afterwards. That area must be the exact same background colour/treatment as the rest of the canvas — never a differently coloured box, panel, strip, or placeholder.

REFERENCE RULE
The selected Google Drive reference image is the main COMPOSITION BLUEPRINT. Preserve its visual logic, density, image-to-text balance, hierarchy, approximate geometry, layering, spacing, decorative complexity, and editorial feel. Adapt content and colours to this brand. Do not copy the reference logo, brand identity, exact wording, phone number, URL, or proprietary artwork.`;

// --- Build the exact on-image copy directly from the sheet row (no AI content invention) ---
const bulletLines = staticContent
  .split(/\r?\n+/)
  .map(s => s.trim())
  .filter(Boolean)
  .slice(0, 6);

const copyJson = {
  headline: hook,
  headline_highlight: '',
  subheadline: '',
  supporting_points: [],
  event_details: [],
  bullets: bulletLines,
  cta_text: cta,
  hero_concept: `${contentAngle} post for Indian nursing students built around the hook: "${hook}"`
};

return [{ json: {
  topic: hook,
  audience: 'Indian nursing students',
  post_type: contentAngle,
  special_details: staticContent,
  cta_override: cta,
  primary_color: primary,
  secondary_color: secondary,
  background_color: background,
  text_color: text,
  brand_kit: brandKit,
  reference_folder_id: 'YOUR_REFERENCE_IMAGES_FOLDER_ID',
  logos_folder_id: 'YOUR_LOGOS_FOLDER_ID',
  output_folder_id: 'YOUR_OUTPUT_FOLDER_ID',
  logo_margin_px: 48,
  sheet_day: day,
  sheet_content_angle: contentAngle,
  sheet_hook: hook,
  sheet_static_content: staticContent,
  sheet_cta: cta,
  sheet_caption: caption,
  copy_json_text: JSON.stringify(copyJson)
} }];

