const item = $input.first();
const j = item.json || {};

function extractText(obj) {
  if (!obj || typeof obj !== 'object') return '';

  if (Array.isArray(obj.output)) {
    for (const out of obj.output) {
      if (out && Array.isArray(out.content)) {
        for (const p of out.content) {
          if (p && typeof p.text === 'string' && p.text.trim()) {
            return p.text.trim();
          }
        }
      }
    }
  }

  if (obj["0"] && Array.isArray(obj["0"].content)) {
    for (const p of obj["0"].content) {
      if (p && typeof p.text === 'string' && p.text.trim()) {
        return p.text.trim();
      }
    }
  }

  if (Array.isArray(obj.content)) {
    for (const p of obj.content) {
      if (p && typeof p.text === 'string' && p.text.trim()) {
        return p.text.trim();
      }
    }
  }

  if (typeof obj.text === 'string' && obj.text.trim()) {
    return obj.text.trim();
  }

  return '';
}

let raw = extractText(j)
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let selected = null;

// First try normal JSON
try {
  selected = JSON.parse(raw);
} catch (e) {
  // Fallback for incomplete/truncated OpenAI output
  const idMatch = raw.match(
    /"selected_reference_id"\s*:\s*"([^"]+)"/
  );

  const nameMatch = raw.match(
    /"selected_reference_name"\s*:\s*"([^"]*)"/
  );

  const reasonMatch = raw.match(
    /"selection_reason"\s*:\s*"([^"]*)"/
  );

  if (!idMatch) {
    throw new Error(
      'Could not find selected_reference_id in Select Best Reference output. Raw output: ' +
      raw.slice(0, 500)
    );
  }

  selected = {
    selected_reference_id: idMatch[1],
    selected_reference_name: nameMatch ? nameMatch[1] : '',
    selection_reason: reasonMatch ? reasonMatch[1] : ''
  };
}

if (!selected.selected_reference_id) {
  throw new Error(
    'Selected reference ID is missing from Select Best Reference output.'
  );
}

if (!j.copy_json_text) {
  throw new Error(
    'copy_json_text is missing. Check Normalize Sheet Row.'
  );
}

// Find the chosen reference directly from reference_library
const referenceLibrary = Array.isArray(j.reference_library)
  ? j.reference_library
  : [];

const chosenReference = referenceLibrary.find(
  ref => String(ref.id) === String(selected.selected_reference_id)
);

if (!chosenReference) {
  throw new Error(
    'Selected reference ID ' +
    selected.selected_reference_id +
    ' was not found in reference_library.'
  );
}

return [{
  json: {
    ...j,

    selected_reference_id:
      selected.selected_reference_id,

    selected_reference_name:
      selected.selected_reference_name ||
      chosenReference.name ||
      '',

    selection_reason:
      selected.selection_reason || '',

    // IMPORTANT:
    // Take the complete analysis from reference_library,
    // NOT from the truncated AI output.
    selected_reference_analysis:
      chosenReference.analysis || '',

    copy_json_text:
      j.copy_json_text
  }
}];

