const imageItems = items
  .filter(item => {
    const mime = String(item.json?.mimeType || '').toLowerCase();
    const name = String(item.json?.name || '').toLowerCase();
    return mime.startsWith('image/') ||
      /\.(png|jpe?g|webp)$/i.test(name);
  })
  .slice(0, 8);

if (!imageItems.length) {
  throw new Error('No PNG/JPG/JPEG/WEBP reference images were found in the fixed Google Drive folder.');
}

return imageItems.map(item => ({
  json: {
    id: item.json.id,
    name: item.json.name || '',
    mimeType: item.json.mimeType || ''
  }
}));

function extractText(obj) {
  if (!obj || typeof obj !== 'object') return '';

  if (obj["0"] && Array.isArray(obj["0"].content)) {
    for (const p of obj["0"].content) {
      if (p && typeof p.text === 'string' && p.text.trim()) return p.text.trim();
    }
  }

  if (Array.isArray(obj.content)) {
    for (const p of obj.content) {
      if (p && typeof p.text === 'string' && p.text.trim()) return p.text.trim();
    }
  }

  if (typeof obj.text === 'string' && obj.text.trim()) return obj.text.trim();

  if (Array.isArray(obj.output)) {
    for (const out of obj.output) {
      if (out && Array.isArray(out.content)) {
        for (const p of out.content) {
          if (p && typeof p.text === 'string' && p.text.trim()) return p.text.trim();
        }
      }
      if (out && typeof out.text === 'string' && out.text.trim()) return out.text.trim();
    }
  }

  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      const found = extractText(value);
      if (found) return found;
    }
  }
  return '';
}

const refs = items.map((item, index) => ({
  index: index + 1,
  id: item.json.id || '',
  name: item.json.name || `Reference ${index + 1}`,
  analysis: extractText(item.json)
})).filter(x => x.id && x.analysis);

if (!refs.length) {
  throw new Error('Reference images were downloaded, but no usable analysis was produced.');
}

return [{
  json: {
    reference_library: refs
  }
}];

const item = $input.first();
const j = item.json || {};
const refs = Array.isArray(j.reference_library) ? j.reference_library : [];

if (!refs.length) {
  throw new Error('Reference library is empty.');
}

const libraryText = refs.map(r =>
  `REFERENCE ${r.index}
ID: ${r.id}
NAME: ${r.name}
ANALYSIS:
${r.analysis}`
).join('\n\n--------------------\n\n');

const prompt = `Select the SINGLE best reference composition for this Study Nursing Abroad post.

POST
Topic: ${j.topic}
Audience: ${j.audience}
Post Type: ${j.post_type}
Special Details: ${j.special_details || '[none]'}

SELECTION CRITERIA
- Choose based on composition suitability, not filename.
- Match the post's information density to the reference.
- Event posts should prefer references with strong date/time/venue/event hierarchy.
- Informational/educational posts should prefer references with suitable structured information areas.
- Promotional posts should prefer references with strong hero + CTA treatment.
- Career/admission posts should prefer references whose visual hierarchy fits the topic.
- Prefer a visually rich, polished reference when the content can support it.
- Do not choose a sparse reference merely because it is easier.

REFERENCE LIBRARY
${libraryText}

Return ONLY valid JSON:
{
  "selected_reference_id": "<exact Drive file ID>",
  "selected_reference_name": "<exact filename>",
  "selection_reason": "<short reason>",
  "selected_reference_analysis": "<copy the key composition rules from the chosen reference analysis>"
}`;

return [{
  json: {
    ...j,
    select_reference_prompt: prompt
  }
}];

const j = $input.first().json || {};
const b64 =
  j?.data?.[0]?.b64_json ||
  j?.data?.[0]?.b64 ||
  j?.b64_json ||
  '';

if (!b64) {
  const url = j?.data?.[0]?.url || j?.url || '';
  if (url) {
    throw new Error('CometAPI returned an image URL instead of b64_json. Current workflow expects base64. URL: ' + url);
  }
  throw new Error('CometAPI did not return data[0].b64_json.');
}

return [{ json: { image_base64: b64, provider: 'CometAPI' } }];

const outBinary = {};
for (const item of items) {
  const file = item.binary?.logo;
  if (!file) continue;
  const name = (item.json?.name || file.fileName || '').toLowerCase();

  if (name.includes('edusarc')) {
    outBinary.edusarc_logo = file;
    continue;
  }

  if (name.includes('black')) outBinary.logo_black = file;
  else if (name.includes('pink')) outBinary.logo_pink = file;
  else if (name.includes('white')) outBinary.logo_white = file;
}
if (!outBinary.logo_black) outBinary.logo_black = outBinary.logo_pink || outBinary.logo_white;
if (!outBinary.logo_black) throw new Error('No usable Study Nursing logo found.');
if (!outBinary.edusarc_logo) throw new Error('No usable EduSarc logo found.');
return [{ json: {}, binary: outBinary }];

const response = $input.first().json;
const image = response.data?.[0];
if (!image) {
  throw new Error('No image returned from CometAPI: ' + JSON.stringify(response).slice(0, 1000));
}
if (image.b64_json) {
  return [{ json: { status: 'success', revised_prompt: image.revised_prompt || '' }, binary: { image: { data: image.b64_json, mimeType: 'image/png', fileName: 'generated-image.png', fileExtension: 'png' } } }];
}
if (image.url) {
  return [{ json: { status: 'success', image_url: image.url, revised_prompt: image.revised_prompt || '' } }];
}
throw new Error('Unsupported image response: ' + JSON.stringify(response).slice(0, 1000));

const j = $input.first().json || {};
const b64 =
  j?.data?.[0]?.b64_json ||
  j?.data?.[0]?.b64 ||
  j?.b64_json ||
  '';

if (!b64) {
  const url = j?.data?.[0]?.url || j?.url || '';
  if (url) {
    throw new Error('CometAPI returned an image URL instead of b64_json. Current workflow expects base64. URL: ' + url);
  }
  throw new Error('CometAPI did not return data[0].b64_json.');
}

return [{ json: { image_base64: b64, provider: 'CometAPI' } }];
